+			block: "function update!(); helper(); end; trailing()",
+			mask: func(block string) string {
+				return juliaMaskLongFormDefinition(block, "update!")
+			},
+		},
+		{
+			name:  "short form",
+			block: "update!() = helper(); trailing()",
+			mask: func(block string) string {
+				return juliaMaskDefinitionHeads(block, []string{"update!"})
+			},
+		},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			calls := juliaCallIdentifiers(tc.mask(tc.block))
+			if _, ok := calls["update!"]; ok {
+				t.Errorf("definition head ending in ! remained visible: %#v", calls)
+			}
+			if _, ok := calls["helper"]; ok {
+				t.Errorf("definition body ending in ! remained visible: %#v", calls)
+			}
+			if _, ok := calls["trailing"]; !ok {
+				t.Errorf("mask swallowed trailing enclosing-scope code: %#v", calls)
+			}
+		})
