+
+// juliaReturnFlowFact records one syntax-proven root call whose value reaches a
+// callable's return. CallOffset is absolute in the source file, matching both
+// the bare and qualified Julia call scanners exactly.
+type juliaReturnFlowFact struct {
+	CallOffset   int
+	EvidenceKind string
+	Variable     string
+}
+
+func juliaReturnFlowFactsByDefinition(root *sitter.Node, src []byte) (map[int][]juliaReturnFlowFact, bool) {
+	out := map[int][]juliaReturnFlowFact{}
+	truncated := false
+	var visit func(*sitter.Node, int)
+	visit = func(node *sitter.Node, depth int) {
+		if !validNode(node) {
+			return
+		}
+		if depth >= maxParseWalkDepth {
+			truncated = true
+			return
+		}
+		if juliaFlowCallableDefinition(node, src) {
+			out[int(node.StartByte())] = juliaCallableReturnFlowFacts(node, src)
+		}
+		for i := 0; i < int(node.NamedChildCount()); i++ {
+			visit(node.NamedChild(i), depth+1)
+		}
+	}
+	visit(root, 0)
+	return out, truncated
+}
+
+func juliaFlowCallableDefinition(node *sitter.Node, src []byte) bool {
+	if !validNode(node) {
+		return false
+	}
+	switch node.Type() {
+	case "function_definition", "macro_definition":
+		return true
+	case "assignment":
+		return node.NamedChildCount() > 0 && juliaDefinitionName(node.NamedChild(0), src) != ""
+	default:
+		return false
+	}
+}
+
