+		if !validNode(node) || depth >= maxParseWalkDepth {
+			return
+		}
+		if node != callable && (juliaFlowCallableDefinition(node, src) || node.Type() == "arrow_function_expression") {
+			return
+		}
+		if node.Type() == "return_statement" {
+			if node.NamedChildCount() > 0 {
+				value := node.NamedChild(0)
+				if value.Type() == "identifier" {
+					if rhs, variable, ok := juliaReachingAssignment(value, src); ok {
+						facts = append(facts, juliaReturnedNodeFacts(rhs, "assigned_return_flow", variable)...)
+					}
+				} else {
+					facts = append(facts, juliaReturnedNodeFacts(value, "return_flow", "")...)
+				}
+			}
+			return
+		}
+		for i := 0; i < int(node.NamedChildCount()); i++ {
+			collectReturns(node.NamedChild(i), depth+1)
+		}
+	}
