+	}
+	var rhs *sitter.Node
+	matched := false
+	for i := 0; i < int(parent.NamedChildCount()); i++ {
+		statement := parent.NamedChild(i)
+		if !validNode(statement) || statement.StartByte() >= value.StartByte() {
