+package sem
+
+import (
+	"context"
+	"strings"
+
+	sitter "github.com/smacker/go-tree-sitter"
+)
+
+// juliaLocalBindingNames returns every name that Julia's syntax binds inside
+// one callable. The same-container CALLS fallback is intentionally fail-closed:
+// a parse failure returns nil, which disables that fallback for the callable.
+func juliaLocalBindingNames(source string) map[string]struct{} {
+	spec, ok := languageForPath("scope.jl")
+	if !ok {
+		return nil
+	}
+	parser := sitter.NewParser()
+	defer parser.Close()
+	parser.SetLanguage(spec.grammar)
+	tree, err := parser.ParseCtx(context.Background(), nil, []byte(source))
+	if err != nil || tree == nil {
+		return nil
+	}
+	defer tree.Close()
+	root := tree.RootNode()
+	if !validNode(root) || root.HasError() {
+		return nil
+	}
+
+	bindings := map[string]struct{}{}
+	var walk func(*sitter.Node)
+	walk = func(node *sitter.Node) {
+		if !validNode(node) {
+			return
+		}
+		firstIsBinding := false
+		switch node.Type() {
+		case "assignment", "compound_assignment_expression", "for_binding", "let_binding":
+			firstIsBinding = true
+		case "catch_clause":
+			firstIsBinding = juliaBindingPattern(node.NamedChild(0), []byte(source), bindings)
+		case "let_statement":
+			// A bare `let name` is not wrapped in a let_binding node.
+			firstIsBinding = juliaBindingPattern(node.NamedChild(0), []byte(source), bindings)
+		case "local_statement":
+			for i := 0; i < int(node.NamedChildCount()); i++ {
+				child := node.NamedChild(i)
+				if !juliaBindingPattern(child, []byte(source), bindings) {
+					walk(child)
+				}
+			}
+			return
+		case "do_clause", "arrow_function_expression":
+			firstIsBinding = juliaBindingPattern(node.NamedChild(0), []byte(source), bindings)
+		}
+		start := 0
+		if firstIsBinding {
+			start = 1
+		}
+		for i := start; i < int(node.NamedChildCount()); i++ {
+			walk(node.NamedChild(i))
+		}
+	}
+	walk(root)
+	return bindings
+}
+
+// juliaBindingPattern records identifiers only from syntactic binding shapes;
+// field/index assignment and type annotations are deliberately excluded.
+func juliaBindingPattern(node *sitter.Node, source []byte, out map[string]struct{}) bool {
+	if !validNode(node) {
+		return false
+	}
